-- Customer bank details under Always Encrypted: the column master key stays in
-- Key Vault (kv-tb-billing-eu) and the server only ever sees ciphertext.

CREATE COLUMN MASTER KEY CMK_BillingKeyVault
WITH (
    KEY_STORE_PROVIDER_NAME = N'AZURE_KEY_VAULT',
    KEY_PATH = N'https://kv-tb-billing-eu.vault.azure.net/keys/always-encrypted-cmk/eea1b20ef397fb26300b69f8ee1e4137'
);
GO

CREATE COLUMN ENCRYPTION KEY CEK_BankDetails
WITH VALUES (
    COLUMN_MASTER_KEY = CMK_BillingKeyVault,
    ALGORITHM = 'RSA_OAEP',
    ENCRYPTED_VALUE = 
);
GO

CREATE TABLE dbo.BankDetails (
    bank_detail_id int IDENTITY(1, 1) NOT NULL PRIMARY KEY,
    customer_id int NOT NULL,
    account_holder nvarchar(140) NOT NULL,
    iban char(34) COLLATE Latin1_General_BIN2
        ENCRYPTED WITH (
            COLUMN_ENCRYPTION_KEY = CEK_BankDetails,
            ENCRYPTION_TYPE = RANDOMIZED,
            ALGORITHM = 'AEAD_AES_256_CBC_HMAC_SHA_256') NOT NULL,
    bic char(11) NULL,
    mandate_reference varchar(35) NULL,
    updated_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME()
);
GO
